from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/api/routes/predictions.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_api_key\nfrom app.schemas.prediction import ExplanationResponse, PredictionRequest, PredictionResponse\nfrom app.services.prediction_service import generate_prediction\n\nrouter = APIRouter(tags=["predictions"])\n\n\n@router.post("/predict-market", response_model=PredictionResponse)\ndef predict_market(\n    payload: PredictionRequest,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> PredictionResponse:\n    try:\n        return PredictionResponse.model_validate(generate_prediction(db, payload))\n    except LookupError as exc:\n        raise HTTPException(\n            status_code=503,\n            detail={"code": "MODEL_OR_STATION_UNAVAILABLE", "message": str(exc), "production_trading_allowed": False},\n        ) from exc\n    except ValueError as exc:\n        raise HTTPException(status_code=422, detail={"code": "PREDICTION_REJECTED", "message": str(exc)}) from exc\n\n\n@router.post("/explain-prediction", response_model=ExplanationResponse)\ndef explain_prediction(\n    payload: PredictionRequest,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> ExplanationResponse:\n    try:\n        result = generate_prediction(db, payload)\n    except LookupError as exc:\n        raise HTTPException(status_code=503, detail={"code": "MODEL_UNAVAILABLE", "message": str(exc)}) from exc\n    distribution = result["prediction_distribution"]\n    return ExplanationResponse(\n        model_version=result["model_version"],\n        predicted_value=result["predicted_value"],\n        top_positive_drivers=result["top_positive_drivers"],\n        top_negative_drivers=result["top_negative_drivers"],\n        model_disagreement=distribution.get("sigma"),\n        station_bias=None,\n        historical_analogues=result["historical_analogues"],\n        warnings=result["warnings"],\n    )\n')
write('app/api/routes/stations.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, Depends, HTTPException, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_admin_key, require_api_key\nfrom app.db.models import Station\nfrom app.schemas.station import StationCreate, StationRead\nfrom app.services.audit_service import record_audit\n\nrouter = APIRouter(prefix="/stations", tags=["stations"])\n\n\ndef _read(station: Station) -> StationRead:\n    return StationRead(\n        id=station.id,\n        station_code=station.station_code,\n        station_name=station.station_name,\n        latitude=station.latitude,\n        longitude=station.longitude,\n        elevation_m=station.elevation_m,\n        timezone=station.timezone,\n        official_source=station.official_source,\n        metadata=station.metadata_json,\n        active=station.active,\n        created_at=station.created_at,\n        updated_at=station.updated_at,\n    )\n\n\n@router.get("", response_model=list[StationRead])\ndef list_stations(\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> list[StationRead]:\n    return [_read(item) for item in db.query(Station).order_by(Station.station_code).all()]\n\n\n@router.post("", response_model=StationRead, status_code=status.HTTP_201_CREATED)\ndef upsert_station(\n    payload: StationCreate,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> StationRead:\n    station = db.query(Station).filter(Station.station_code == payload.station_code).one_or_none()\n    created = station is None\n    if station is None:\n        station = Station(station_code=payload.station_code, station_name=payload.station_name, latitude=payload.latitude, longitude=payload.longitude)\n        db.add(station)\n    station.station_name = payload.station_name\n    station.latitude = payload.latitude\n    station.longitude = payload.longitude\n    station.elevation_m = payload.elevation_m\n    station.timezone = payload.timezone\n    station.official_source = payload.official_source\n    station.metadata_json = payload.metadata\n    station.active = payload.active\n    db.commit()\n    db.refresh(station)\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="station.created" if created else "station.updated",\n        entity_type="station",\n        entity_id=station.id,\n        details={"station_code": station.station_code},\n    )\n    return _read(station)\n\n\n@router.get("/{station_code}", response_model=StationRead)\ndef get_station(\n    station_code: str,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> StationRead:\n    station = db.query(Station).filter(Station.station_code == station_code).one_or_none()\n    if station is None:\n        raise HTTPException(status_code=404, detail={"code": "STATION_NOT_FOUND", "message": station_code})\n    return _read(station)\n')
write('app/api/routes/training.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_admin_key\nfrom app.core.config import get_settings\nfrom app.db.models import DatasetManifest, TrainingJob\nfrom app.schemas.training import TrainCandidateRequest, TrainingJobRead\nfrom app.services.audit_service import record_audit\nfrom app.services.training_service import execute_training_job\nfrom app.workers.tasks import train_candidate_task\n\nrouter = APIRouter(prefix="/training", tags=["training"])\n\n\ndef _read(job: TrainingJob) -> TrainingJobRead:\n    return TrainingJobRead.model_validate(job)\n\n\ndef _execute_local(job_id: str) -> None:\n    from app.db.session import SessionLocal\n\n    with SessionLocal() as db:\n        execute_training_job(db, job_id)\n\n\n@router.post("/train-candidate", response_model=TrainingJobRead, status_code=status.HTTP_202_ACCEPTED)\ndef train_candidate(\n    payload: TrainCandidateRequest,\n    background_tasks: BackgroundTasks,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> TrainingJobRead:\n    if db.get(DatasetManifest, payload.dataset_id) is None:\n        raise HTTPException(status_code=404, detail={"code": "DATASET_NOT_FOUND", "message": payload.dataset_id})\n    configuration = payload.model_dump(exclude={"dataset_id", "model_name", "requested_version"})\n    job = TrainingJob(\n        dataset_id=payload.dataset_id,\n        model_name=payload.model_name,\n        requested_version=payload.requested_version,\n        configuration=configuration,\n    )\n    db.add(job)\n    db.commit()\n    db.refresh(job)\n    settings = get_settings()\n    if settings.task_always_eager:\n        background_tasks.add_task(_execute_local, job.id)\n    else:\n        train_candidate_task.delay(job.id)\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="training.requested",\n        entity_type="training_job",\n        entity_id=job.id,\n        details={"dataset_id": payload.dataset_id},\n    )\n    return _read(job)\n\n\n@router.get("/{job_id}", response_model=TrainingJobRead)\ndef get_training_job(\n    job_id: str,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_admin_key),\n) -> TrainingJobRead:\n    job = db.get(TrainingJob, job_id)\n    if job is None:\n        raise HTTPException(status_code=404, detail={"code": "TRAINING_JOB_NOT_FOUND", "message": job_id})\n    return _read(job)\n')
write('app/cli.py', 'from __future__ import annotations\n\nimport argparse\nimport json\nimport secrets\nfrom pathlib import Path\n\nfrom app.db.base import Base\nfrom app.db.models import Station\nfrom app.db.session import SessionLocal, engine\nfrom app.services.model_service import model_health\n\n\ndef init_db() -> None:\n    Base.metadata.create_all(bind=engine)\n    print("Database initialized.")\n\n\ndef seed_stations(path: str) -> None:\n    records = json.loads(Path(path).read_text())\n    with SessionLocal() as db:\n        for payload in records:\n            station = (\n                db.query(Station)\n                .filter(Station.station_code == payload["station_code"])\n                .one_or_none()\n            )\n            if station is None:\n                station = Station(\n                    station_code=payload["station_code"],\n                    station_name=payload["station_name"],\n                    latitude=payload["latitude"],\n                    longitude=payload["longitude"],\n                )\n                db.add(station)\n            station.station_name = payload["station_name"]\n            station.latitude = payload["latitude"]\n            station.longitude = payload["longitude"]\n            station.elevation_m = payload.get("elevation_m")\n            station.timezone = payload.get("timezone", "UTC")\n            station.official_source = payload.get("official_source")\n            station.metadata_json = payload.get("metadata", {})\n        db.commit()\n    print(f"Seeded {len(records)} stations.")\n\n\ndef print_health() -> None:\n    with SessionLocal() as db:\n        payload = model_health(db)\n    print(json.dumps(payload, indent=2, default=str))\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(prog="weather-ml")\n    subparsers = parser.add_subparsers(dest="command", required=True)\n    subparsers.add_parser("init-db")\n    seed = subparsers.add_parser("seed-stations")\n    seed.add_argument("path", nargs="?", default="config/stations.example.json")\n    subparsers.add_parser("model-health")\n    subparsers.add_parser("generate-key")\n    args = parser.parse_args()\n    if args.command == "init-db":\n        init_db()\n    elif args.command == "seed-stations":\n        seed_stations(args.path)\n    elif args.command == "model-health":\n        print_health()\n    elif args.command == "generate-key":\n        print(secrets.token_urlsafe(48))\n\n\nif __name__ == "__main__":\n    main()\n')
